module.exports = function () {
  const r = {};
  try { r.secret = Deno.env.get("SECRET"); } catch { r.secret = "DENIED"; }
  try { r.other = Deno.env.get("OTHER"); } catch { r.other = "DENIED"; }
  try { r.fsOk = Deno.readTextFileSync("./data/ok.txt").trim(); } catch { r.fsOk = "DENIED"; }
  try { r.fsEscape = Deno.readTextFileSync("./data/../secret.txt").trim(); } catch { r.fsEscape = "DENIED"; }
  return r;
};
